import * as http from 'node:http';
async function main(): Promise<void> {
  const log: string[] = [];
  let done: () => void = () => {};
  const closed = new Promise<void>((resolve) => { done = resolve; });
  const srv = http.createServer((req, res) => {
    res.on('finish', () => { log.push('finish:' + res.writableFinished); });
    res.once('close', () => { log.push('close:' + res.writableFinished); done(); });
    res.end('x');
    log.push('after-end:' + res.writableEnded + ':' + res.finished);
  });
  await new Promise<void>((r) => srv.listen(0, '127.0.0.1', () => r()));
  const r = await fetch('http://127.0.0.1:' + (srv.address() as any).port + '/');
  console.log(await r.text());
  await closed;
  console.log(log.join(','));
  srv.close();
}
